import { test, expect } from '@playwright/test';

test.describe('Error clearing on input correction', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('data:text/html,<html><body><form><input id="email" type="email" placeholder="Enter email" /><span id="error" style="color: red; display: none;">Invalid email format</span><button type="submit">Submit</button></form><script>const input = document.getElementById("email"); const error = document.getElementById("error"); input.addEventListener("blur", () => { if (input.value && !input.value.includes("@")) { error.style.display = "block"; } }); input.addEventListener("input", () => { if (input.value.includes("@")) { error.style.display = "none"; } }); </script></body></html>');
  });

  test('should display error when invalid input is entered', async ({ page }) => {
    const emailInput = page.getByPlaceholder('Enter email');
    const errorMessage = page.getByText('Invalid email format');

    await emailInput.fill('invalidemail');
    await emailInput.blur();

    await expect(errorMessage).toBeVisible();
  });

  test('should clear error when input is corrected', async ({ page }) => {
    const emailInput = page.getByPlaceholder('Enter email');
    const errorMessage = page.getByText('Invalid email format');

    await emailInput.fill('invalidemail');
    await emailInput.blur();
    await expect(errorMessage).toBeVisible();

    await emailInput.fill('valid@email.com');
    await expect(errorMessage).toBeHidden();
  });

  test('should not show error for valid input from start', async ({ page }) => {
    const emailInput = page.getByPlaceholder('Enter email');
    const errorMessage = page.getByText('Invalid email format');

    await emailInput.fill('correct@email.com');
    await emailInput.blur();

    await expect(errorMessage).toBeHidden();
  });
});
